! ============================================================
! VML 文件 I/O 扩展库 — Fortran
!
! 使用示例:
!   call asm("SYSCALL 110")   ! 打开文件
!   call asm("SYSCALL 112")   ! 读取文件
!   call asm("SYSCALL 113")   ! 写入文件
!   call asm("SYSCALL 114")   ! 文件控制 (定位/大小)
!   call asm("SYSCALL 111")   ! 关闭文件
! ============================================================

! ============================================================
! SYSCALL 110 — FileOpen
! 打开或创建文件
! 参数:
!   R0 = 文件名地址 (\0 结尾)
!   R1 = 模式: 0=只读, 1=只写(创建), 2=读写
! 返回: R0 = 文件句柄 (>=0 成功), <0 = 错误
!
! Fortran 使用示例:
!   ! 打开文件 "data.txt" 只读
!   ! R0 = "data.txt\0" 的地址
!   ! R1 = 0 (只读模式)
!   call asm("SYSCALL 110")
!   ! 返回: R0 = 文件句柄, <0 表示打开失败
! ============================================================

! ============================================================
! SYSCALL 111 — FileClose
! 关闭文件
! 参数: R0 = 文件句柄
! 返回: R0 = 0 成功, <0 失败
!
! Fortran 使用示例:
!   ! R0 = 文件句柄
!   call asm("SYSCALL 111")
! ============================================================

! ============================================================
! SYSCALL 112 — FileRead
! 从文件读取数据到缓冲区
! 参数:
!   R0 = 文件句柄
!   R1 = 缓冲区地址
!   R2 = 读取字节数
! 返回: R0 = 实际读取字节数 (0=EOF), <0 = 错误
!
! Fortran 使用示例:
!   ! 从句柄 fd 读取 1024 字节到缓冲区
!   ! R0 = fd, R1 = 缓冲区地址, R2 = 1024
!   call asm("SYSCALL 112")
!   ! 返回: R0 = 实际读取的字节数
! ============================================================

! ============================================================
! SYSCALL 113 — FileWrite
! 将缓冲区数据写入文件
! 参数:
!   R0 = 文件句柄
!   R1 = 数据地址
!   R2 = 写入字节数
! 返回: R0 = 实际写入字节数, <0 = 错误
!
! Fortran 使用示例:
!   ! 向句柄 fd 写入 256 字节
!   ! R0 = fd, R1 = 数据地址, R2 = 256
!   call asm("SYSCALL 113")
! ============================================================

! ============================================================
! SYSCALL 114 — FileControl
! 控制文件操作 (定位、截断、查询)
! 参数:
!   R0 = 文件句柄
!   R1 = 命令:
!     0 = 获取文件大小 -> R2 忽略, 返回 R0 = 大小
!     1 = 定位 -> R2 = 偏移量
!     2 = 获取当前位置 -> 返回 R0 = 当前位置
!     3 = 截断 -> R2 = 新文件大小
! 返回: R0 = 命令结果
!
! Fortran 使用示例:
!   ! 获取文件大小
!   ! R0 = fd, R1 = 0
!   call asm("SYSCALL 114")
!   ! 返回: R0 = 文件大小 (字节)
!
!   ! 定位到文件开头
!   ! R0 = fd, R1 = 1 (Seek), R2 = 0 (偏移 0)
!   call asm("SYSCALL 114")
!
!   ! 获取文件当前位置
!   ! R0 = fd, R1 = 2
!   call asm("SYSCALL 114")
!   ! 返回: R0 = 当前读写位置
! ============================================================

! ============================================================
! VML 汇编共享库 CALL 目标 (文件操作):
!   CALL fopen       — 打开文件
!   CALL fclose      — 关闭文件
!   CALL fread       — 读取文件
!   CALL fwrite      — 写入文件
!   CALL fseek       — 文件定位
!   CALL ftell       — 获取文件位置
!   CALL fsize       — 获取文件大小
!   CALL ftruncate   — 文件截断
! ============================================================
